import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.Crpw6aS5.js";const h=JSON.parse('{"title":"拉尔夫·谢伊","description":"","frontmatter":{"title":"拉尔夫·谢伊","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/拉尔夫·谢伊.md","filePath":"04_people/拉尔夫·谢伊.md"}'),l={name:"04_people/拉尔夫·谢伊.md"};function i(n,t,s,_,c,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="拉尔夫·谢伊" tabindex="-1">拉尔夫·谢伊 <a class="header-anchor" href="#拉尔夫·谢伊" aria-label="Permalink to &quot;拉尔夫·谢伊&quot;">​</a></h1><ul><li><strong>角色职位</strong>：世界图书（World Book）、Kirby、Scott Fetzer 管理者</li><li><strong>与巴菲特关系</strong>：伯克希尔·哈撒韦旗下多家子公司运营负责人</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>拉尔夫·谢伊是伯克希尔·哈撒韦旗下多家重要子公司的核心管理者。在他的管理下，世界图书公司保持着稳健的运营，成为伯克希尔大家庭中可靠的事业板块。谢伊负责运营的Scott Fetzer子公司群涵盖多个细分业务领域，他以精简高效的管理风格著称。</p><p>谢伊在伯克希尔的角色体现了巴菲特一贯的经营理念——找到优秀的管理人才，充分授权，让他们自主运营。作为一名低调但能力出众的管理者，谢伊在巴菲特收购后的整合过程中发挥了关键作用，确保各子公司在伯克希尔的伞下继续健康发展。</p><p>巴菲特对谢伊的管理能力颇为信任，将多家业务性质各异的公司交由其统一协调管理，这种&quot;一个优秀管理者、多项分散业务&quot;的模式，正是伯克希尔商业模式的一个缩影。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1986年</strong>：随伯克希尔收购Scott Fetzer，成为旗下多家子公司管理者</li><li><strong>1990年代</strong>：持续管理世界图书、Kirby等子公司，保持稳定盈利</li><li><strong>2000年代</strong>：继续担任Scott Fetzer业务群的管理职责</li></ul>',8)])])}const u=e(l,[["render",i]]);export{h as __pageData,u as default};
